    ("Accuracy", "Share of all predictions that are correct; misleading for rare events."),
    ("Agent", "An LLM system that plans and uses tools in a loop to complete a task."),
    ("A/B test", "Randomly splitting users between two versions to measure the effect of a change."),
    ("Attention", "The transformer mechanism that lets each token weigh the relevance of other tokens."),
    ("Backpropagation", "The method for computing how much each weight contributed to the error."),
    ("Baseline", "A simple reference solution that a model must beat."),
    ("Concept drift", "When the relationship between inputs and outcomes changes over time."),
    ("Context window", "The maximum number of tokens a model can consider at once."),
    ("Data drift", "When production input data differs from training data."),
    ("Data leakage", "Test or future information sneaking into training, inflating results."),
    ("Embedding", "A list of numbers representing an item so similar items are close together."),
    ("Eval", "A repeatable test that scores a model or AI system on representative examples."),
    ("F1 score", "The harmonic mean of precision and recall."),
    ("Feature", "An input variable a model uses to make a prediction."),
    ("Fine-tuning", "Further training a pretrained model on task-specific data."),
    ("Gradient descent", "Adjusting parameters in small steps to reduce error."),
    ("Hallucination", "A fluent but false or unsupported model output."),
    ("Hyperparameter", "A setting chosen by people, such as learning rate or number of layers."),
    ("Inference", "Running a trained model to get predictions or outputs."),
    ("Label", "The correct answer attached to a training example."),
    ("LLM", "Large language model: a transformer trained on large text collections to predict tokens."),
    ("MLOps", "Practices for versioning, deploying, monitoring and retraining ML systems."),
    ("Overfitting", "When a model memorizes training data and performs poorly on new data."),
    ("Parameter", "A weight learned during training; '7B' means about 7 billion."),
    ("Precision", "Of the items predicted positive, the share that really are positive."),
    ("Prompt injection", "Malicious instructions hidden in content that a model may follow."),
    ("Quantization", "Storing model weights with fewer bits to save memory and cost."),
    ("RAG", "Retrieval-augmented generation: adding retrieved passages to a prompt to ground answers."),
    ("Recall", "Of the real positives, the share the model found."),
    ("RLHF", "Reinforcement learning from human feedback: tuning a model toward preferred answers."),
    ("Token", "A chunk of text (often part of a word) that models read and are billed by."),
